import type { IncomingMessage, ServerResponse } from 'http';
// @ts-ignore: generated by `npm run build` (esbuild bundle of server.ts); plain ESM extensionless imports cannot run on Vercel
import { createExpressApp } from './_server.cjs';

let cachedAppPromise: Promise<any> | null = null;

export default async function handler(req: IncomingMessage, res: ServerResponse) {
  if (!cachedAppPromise) {
    cachedAppPromise = createExpressApp();
  }
  const app = await cachedAppPromise;
  return app(req, res);
}
